fn prime_num(n: u64) -> bool {
    if n < 2 {
        // According to problem statement, n >= 2, but just in case
        return false;
    }
    // Only need to check divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return false;
        }
    }
    true
}